import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Professions in Syrolands","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/overview.md","filePath":"en/guide/professions/overview.md"}'),o={name:"en/guide/professions/overview.md"};function i(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="professions-in-syrolands" tabindex="-1">Professions in Syrolands <a class="header-anchor" href="#professions-in-syrolands" aria-label="Permalink to &quot;Professions in Syrolands&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Crafts belong to adventurers, with field, exploration and economic utility.</li><li>Skill, techniques, practice and reputation create a profession identity.</li><li>Knowledge and interactive work matter beyond skill totals; these systems remain Proposed.</li></ul><p>Crafts belong to adventurers. They should create useful choices in exploration, survival, maintenance and trade without becoming generic combat buffs.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>What it means</th></tr></thead><tbody><tr><td>Skill</td><td>Broad capability in the shared character budget</td></tr><tr><td>Technique</td><td>Learned knowledge, such as Distillation or Bowmaking</td></tr><tr><td>Profession path</td><td>Skill + techniques + practice</td></tr><tr><td>Identity</td><td>What others know you make well</td></tr><tr><td>Journal</td><td>Discoveries learned through teachers, books, observation and experiments</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Direction</th></tr></thead><tbody><tr><td>Starting knowledge</td><td>Low skill already offers useful work</td></tr><tr><td>Practice</td><td>Skill broadens capable work and consistency</td></tr><tr><td>Discovery</td><td>Knowledge opens options; 100 does not reveal everything</td></tr><tr><td>Mastery</td><td>Techniques, reputation and understanding matter beyond skill totals</td></tr><tr><td>Production</td><td>Known procedures may support station batches using time and materials</td></tr></tbody></table><p>The proposed shared cap is roughly 700 total / 100 normal per skill, not finalized settings. Seven maxed skills are not required for viability. Commissions reward useful results; reputation reflects actual work. Advice can be shared, but execution still matters.</p><h2 id="explore-the-professions" tabindex="-1">Explore the professions <a class="header-anchor" href="#explore-the-professions" aria-label="Permalink to &quot;Explore the professions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profession</th><th>Role</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/en/guide/professions/cooking.html">Cooking</a></td><td>Food, preparation and survival</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a></td><td>Reactions, preparations and field support</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a></td><td>Geology, extraction and authored excavation</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a></td><td>Metallurgy, equipment and maintenance</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a></td><td>Fit, flexible protection and fashion</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a></td><td>Timber selection and felling</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a></td><td>Woodwork, construction and learned Bowmaking</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a></td><td>Mechanisms, security and devices</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a></td><td>Scrolls, variants, grimoires and notation</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An explorer who knows Blacksmithing can contribute equipment maintenance without becoming a workshop-only character.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/progression.html">Progression</a> · <a href="/Syrolands-Public/en/guide/characters/skills.html">Teachers</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/en/guide/characters/character-creation.html">Backgrounds</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Full specification</a></p><p><span id="crafts-belong-to-adventurers"></span><span id="learning-and-becoming-known"></span><span id="knowledge-and-production"></span><span id="shared-character-rules"></span><span id="inscription-and-magical-knowledge"></span></p>',17)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
